// Parse and validate input
// Phase 2: EN-pivot with structured output generation
const input = $input.first().json;
const body = input.body || input;

const languageNames = {
  'fr': 'français',
  'en': 'English',
  'es': 'español',
  'he': 'hébreu',
  'ar': 'araméen',
  'de': 'allemand',
  'it': 'italien'
};

if (!body.text) {
  return [{
    json: {
      success: false,
      error: { code: 'MISSING_TEXT', message: 'text is required' }
    }
  }];
}

if (!body.api_key) {
  return [{
    json: {
      success: false,
      error: { code: 'MISSING_API_KEY', message: 'api_key is required' }
    }
  }];
}

const sourceLanguage = body.source_language || 'he';
const targetLanguage = body.target_language || 'fr';
const referenceTranslation = body.reference_translation || null;
const hasReferenceTranslation = !!referenceTranslation;

// Phase 2: Determine translation strategy
// - hasReferenceTranslation=true → use existing EN as pivot (Phase 1)
// - hasReferenceTranslation=false AND target!='en' → generate EN+target structured
// - target='en' → direct HE→EN translation
const needsStructuredGeneration = !hasReferenceTranslation && targetLanguage !== 'en' && sourceLanguage !== 'en';
const isDirectToEnglish = targetLanguage === 'en';

return [{
  json: {
    jobId: body.job_id,
    segmentId: body.segment_id || null,
    text: body.text,
    referenceTranslation: referenceTranslation,
    hasReferenceTranslation: hasReferenceTranslation,
    needsStructuredGeneration: needsStructuredGeneration,
    isDirectToEnglish: isDirectToEnglish,
    sourceLanguage: sourceLanguage,
    sourceLangName: languageNames[sourceLanguage] || sourceLanguage,
    targetLanguage: targetLanguage,
    targetLangName: languageNames[targetLanguage] || targetLanguage,
    apiKey: body.api_key,
    model: body.model || 'claude-sonnet-4-20250514',
    context: body.context || {},
    metadata: body.metadata || {}
  }
}];

// Phase 2: Extract structured EN+target translation from single LLM call
const input = $input.first().json;
const prevData = $('Parse Input').first().json;

try {
  const body = input.body || input;

  if (body.error) {
    // Fallback: if structured call fails, return error for fallback handling
    return [{
      json: {
        success: false,
        fallbackToDirectTranslation: true,
        error: { code: 'CLAUDE_ERROR', message: body.error.message || 'Claude API error' },
        ...prevData
      }
    }];
  }

  const content = body.content?.[0]?.text || '';
  const usage = body.usage || {};

  if (!content) {
    return [{
      json: {
        success: false,
        fallbackToDirectTranslation: true,
        error: { code: 'EMPTY_RESPONSE', message: 'Claude returned empty response' },
        ...prevData
      }
    }];
  }

  // Parse JSON from response (handle potential markdown code blocks)
  let parsed;
  try {
    let jsonStr = content.trim();
    // Remove markdown code block if present
    if (jsonStr.startsWith('```')) {
      jsonStr = jsonStr.replace(/^```(?:json)?\n?/, '').replace(/\n?```$/, '');
    }
    parsed = JSON.parse(jsonStr);
  } catch (parseErr) {
    // JSON parse failed - fallback to direct translation
    return [{
      json: {
        success: false,
        fallbackToDirectTranslation: true,
        error: { code: 'JSON_PARSE_ERROR', message: 'Failed to parse structured response: ' + parseErr.message },
        ...prevData
      }
    }];
  }

  // Validate required fields
  if (!parsed.english_pivot || !parsed.translation) {
    return [{
      json: {
        success: false,
        fallbackToDirectTranslation: true,
        error: { code: 'INVALID_STRUCTURE', message: 'Missing english_pivot or translation in response' },
        ...prevData
      }
    }];
  }

  // Success: return both translations
  return [{
    json: {
      success: true,
      translation: parsed.translation,
      english_pivot: parsed.english_pivot,
      method: 'structured_generation',
      generated_english: true,
      segment_id: prevData.segmentId,
      target_language: prevData.targetLanguage,
      tokens: {
        input_tokens: usage.input_tokens || 0,
        output_tokens: usage.output_tokens || 0
      }
    }
  }];
} catch (e) {
  return [{
    json: {
      success: false,
      fallbackToDirectTranslation: true,
      error: { code: 'PARSE_ERROR', message: e.message },
      ...prevData
    }
  }];
}

// Phase 2: Extract fallback direct translation (HE→target without EN pivot)
const input = $input.first().json;
const prevData = $('Extract Structured').first().json;

try {
  const body = input.body || input;

  if (body.error) {
    return [{
      json: {
        success: false,
        error: { code: 'CLAUDE_ERROR', message: body.error.message || 'Claude API error in fallback' }
      }
    }];
  }

  const content = body.content?.[0]?.text || '';
  const usage = body.usage || {};

  if (!content) {
    return [{
      json: {
        success: false,
        error: { code: 'EMPTY_RESPONSE', message: 'Claude returned empty response in fallback' }
      }
    }];
  }

  // Log the original error that caused fallback
  const originalError = prevData.error || null;

  return [{
    json: {
      success: true,
      translation: content,
      english_pivot: null,
      method: 'direct_fallback',
      generated_english: false,
      fallback_reason: originalError ? originalError.code : 'unknown',
      tokens: {
        input_tokens: usage.input_tokens || 0,
        output_tokens: usage.output_tokens || 0
      }
    }
  }];
} catch (e) {
  return [{
    json: {
      success: false,
      error: { code: 'PARSE_ERROR', message: e.message }
    }
  }];
}

// Extract direct translation
// RFC bilingual-translations-en-pivot: track EN pivot usage
const input = $input.first().json;
const prevData = $('Parse Input').first().json;

try {
  const body = input.body || input;

  if (body.error) {
    return [{
      json: {
        success: false,
        error: { code: 'CLAUDE_ERROR', message: body.error.message || 'Claude API error' }
      }
    }];
  }

  const content = body.content?.[0]?.text || '';
  const usage = body.usage || {};

  if (!content) {
    return [{
      json: {
        success: false,
        error: { code: 'EMPTY_RESPONSE', message: 'Claude returned empty response' }
      }
    }];
  }

  // RFC: indicate if EN pivot was used
  const usedEnPivot = prevData.hasReferenceTranslation === true;

  return [{
    json: {
      success: true,
      translation: content,
      method: usedEnPivot ? 'en_pivot' : 'direct',
      used_en_reference: usedEnPivot,
      tokens: {
        input_tokens: usage.input_tokens || 0,
        output_tokens: usage.output_tokens || 0
      }
    }
  }];
} catch (e) {
  return [{
    json: {
      success: false,
      error: { code: 'PARSE_ERROR', message: e.message }
    }
  }];
}
